'use strict'

const { test } = require('node:test')
const Fastify = require('..')

const requestInstanceProperties = ['id', 'params', 'raw', 'query', 'log', 'body']
const replyInstanceProperties = ['raw', 'request', 'log']

test('hasRequestDecorator should detect constructor-assigned properties', t => {
  t.plan(requestInstanceProperties.length)
  const fastify = Fastify()

  for (const name of requestInstanceProperties) {
    t.assert.ok(fastify.hasRequestDecorator(name), `${name} should be detected`)
  }
})

test('hasReplyDecorator should detect constructor-assigned properties', t => {
  t.plan(replyInstanceProperties.length)
  const fastify = Fastify()

  for (const name of replyInstanceProperties) {
    t.assert.ok(fastify.hasReplyDecorator(name), `${name} should be detected`)
  }
})

test('decorateRequest should throw on constructor-assigned properties', t => {
  t.plan(requestInstanceProperties.length)
  const fastify = Fastify()

  for (const name of requestInstanceProperties) {
    t.assert.throws(() => fastify.decorateRequest(name, null), {
      code: 'FST_ERR_DEC_ALREADY_PRESENT'
    })
  }
})

test('decorateReply should throw on constructor-assigned properties', t => {
  t.plan(replyInstanceProperties.length)
  const fastify = Fastify()

  for (const name of replyInstanceProperties) {
    t.assert.throws(() => fastify.decorateReply(name, null), {
      code: 'FST_ERR_DEC_ALREADY_PRESENT'
    })
  }
})

test('constructor-assigned properties are also protected in encapsulated contexts and with trustProxy', (t, done) => {
  t.plan(5)
  const fastify = Fastify({ trustProxy: true })

